  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://s2.affiliatly.com/af-1052238/affiliate.panel?mode=register', 'affiliate_network', 'compensation', 'The program''s Affiliatly panel states: 5% per sale on any referred purchase (new or existing customers), paid every 50 days via PayPal; commissions are earned via coupon code only, not links; affiliate codes give customers 10% off; a code must generate at least $200 a month to stay active. The panel contains no earnings-cap statement, so the cap is unknown (the $200/month figure is an activity threshold, not an earnings cap), and no creator-count evidence was found, so saturation is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://s2.affiliatly.com/af-1052238/affiliate.panel?mode=register', 'affiliate_network', 'ugc_collab', 'The panel promises affiliates who create content with their own photos promotion on the brand''s Instagram and website (notify via pr@adeptcosmetics.com or tag the brand), and top earners receive new releases for free.', 'verified', now());
