  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 8, 11, 7, 2, '{"niche_fit": "Indie makeup brand whose palettes are staples of creator swatch and review content \u2014 a good beauty niche fit.", "ugc_evidence": "The brand explicitly promotes affiliates who create content with their own photos on its Instagram and website, and top earners receive new releases free.", "compensation": "A published 5% per sale, paid via PayPal every 50 days; code-only tracking and a $200/month activity threshold for codes keep this modest; no cap statement found.", "contact_access": "A published PR email (pr@adeptcosmetics.com) plus an affiliate application page on the brand''s own site.", "opportunity_availability": "Open registration through the brand''s own affiliate page and Affiliatly panel, subject to the monthly activity threshold.", "credibility": "A small independent brand with an engaged creator community but limited scale and press."}'::jsonb);
