  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.skinfix.com', 'listing', 'affiliate', 'Rateful''s TikTok Shop brand data shows roughly 91% of Skinfix''s estimated $48.8K in TikTok Shop sales in the 30 days to November 6, 2026 came through affiliate creators, who add products to their showcase and can request free samples via the affiliate center — confirming an active TikTok Shop affiliate program. No published commission percentage was found in any fetched source, so the rate is null. A Sovrn listing exists but its terms were not verified.', 'publicly_reported', now());
