  insert into public.brands (name, website, description, country, status) values ('Avec Les Filles', 'https://aveclesfilles.com', 'Los Angeles-born women''s fashion brand launched in 2017 (''avec les filles'' means ''with the girls'' in French), selling Parisian-inspired outerwear and ready-to-wear - coats, dresses, tailoring and occasion pieces - through its own online store.', 'United States', 'published') returning id into bid;
