  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aveclesfilles.com/pages/affiliate-program', 'official_site', 'affiliate', 'The brand''s own affiliate program page states ''UNCAPPED EARNINGS: There is no cap on how much you can sell. The more you sell the more commission you earn. It''s unlimited!'' - an explicit no-earnings-cap statement on a page the brand itself publishes, so the program is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aveclesfilles.com/pages/affiliate-program', 'official_site', 'compensation', 'The same page advertises ''COMPETITIVE COMMISSION: Earn up to 20% on orders'' - ''up to 20%'' is a rate ceiling rather than a set rate, so no single commission rate is recorded.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aveclesfilles.com/pages/affiliate-program', 'official_site', 'ugc_collab', 'The page is written for content creators and influencers: it offers content assets, custom discount codes, monthly launch updates and occasional cash offers for high-converting content, and invites LTK creators to include their LTK details in the application form on the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://aveclesfilles.com/', 'official_site', 'general', 'The brand''s homepage positions Avec Les Filles as women''s outerwear and ready-to-wear and describes its foundation donating a portion of every sale to women''s empowerment charities.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 15, 11, 8, 4, '{"niche_fit": "Pure women''s fashion - outerwear and ready-to-wear with a Parisian-inspired, highly shoppable aesthetic - squarely in the fashion creator niche.", "ugc_evidence": "The brand''s own program page speaks directly to content creators and influencers, supplies content assets and discount codes, pays cash offers for high-converting content and courts LTK creators.", "compensation": "Verified uncapped earnings on the brand''s own page with an advertised ceiling of up to 20% - strong terms, though the exact rate is set per affiliate, so it sits below the very top band.", "contact_access": "A public application form on the brand''s own affiliate page; no public partnerships email was found.", "opportunity_availability": "Applications are publicly open on the official site, subject to brand review and approval.", "credibility": "Established DTC brand launched in 2017 with its own store and a charitable foundation, but a smaller retail footprint than national chains."}'::jsonb);
