  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.newbalance.com/affiliate/', 'official_site', 'affiliate', 'New Balance''s own affiliate page says enrollment is open to family-friendly website operators subject to being an Impact member and the program terms, with no fee to join, and approved sites earn commissions on click-through sales to newbalance.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.newbalance.com/affiliate/', 'official_site', 'compensation', 'The page''s FAQ states ''Commission rates start at 2% with opportunity to increase based on performance'', a 30-day cookie, average order size of $125+, and gift cards and select products non-commissionable - the published 2% starting rate is recorded.', 'verified', now());
