  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 7, 10, 8, 5, '{"niche_fit": "Footwear and apparel are core fashion-creator categories and New Balance''s lifestyle lines are staples of sneaker and outfit content.", "ugc_evidence": "The published program is publisher- and website-oriented rather than a structured creator community, though the brand is heavily featured in creator content; mid-range per the rubric.", "compensation": "A published 2% starting rate on the brand''s own page is low for the category, partly offset by $125+ average orders and performance increases.", "contact_access": "A dedicated affiliate page on the brand''s own site routes applications through Impact; no public partnerships email was published there.", "opportunity_availability": "Enrollment is publicly open via Impact with no joining fee, subject to application review.", "credibility": "One of the world''s largest footwear brands, headquartered in Boston with global retail and wholesale distribution."}'::jsonb);
