  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 8, 12, 8, 4, '{"niche_fit": "Occasion, prom and going-out dresses are a core fashion-creator category, and the brand designs specifically for social-first shoppers.", "ugc_evidence": "Its Awin profile explicitly courts fashion influencers and content creators, offers exclusive partnerships, and the brand''s social presence is built on creator and customer content.", "compensation": "Commission exists with an advertised ceiling (up to 7% on Awin; up to 10% claimed on the brand''s US page) but the conflicting ceilings mean no verified set rate - mid-range.", "contact_access": "A published affiliate team email on the network profile plus a direct Awin application route.", "opportunity_availability": "Open application through Awin with regular feeds and newsletters for affiliates.", "credibility": "Established UK retailer founded in 2007 with nine international sites and over a million monthly visitors, though without major third-party retail distribution."}'::jsonb);
