  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 6, 10, 8, 5, '{"niche_fit": "Travel insurance is a standard monetization category for travel creators, though narrower than gear or booking brands.", "ugc_evidence": "The brand''s own program page explicitly names travel bloggers, content creators and influencers as target affiliates, but there is no public creator community or content program beyond that.", "compensation": "Referral fees are confirmed by the brand but unpublished, and third-party rate reports conflict - low-mid range.", "contact_access": "A dedicated program page on the brand''s own site with a Partnership Team contact route.", "opportunity_availability": "The marketing affiliate program is publicly open to bloggers, creators and influencers on the official site.", "credibility": "Long-established US travel insurer with an A+ rated underwriting heritage, global assistance operations and a strong expatriate niche."}'::jsonb);
