  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cpsbee.com/en/programs/nomad-esim', 'affiliate_network', 'affiliate', 'CPSbee''s program record, sourced from the program''s official pages and verified October 14, 2026, states the standard Nomad eSIM affiliate rate starts at 10% per successful purchase via Impact.com, with 30-day attribution, monthly payouts and no follower minimum in the FAQ.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateresearch.info/affiliate/nomad-esim/', 'listing', 'affiliate', 'Affiliate Research''s first-party-source review (September 2026) confirms Nomad migrated its affiliate program to Impact.com in August 2025, with a standard rate starting at 10%, higher tiers by partner type and performance, and a separate Creator Partner track for video creators.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/nomad-esim-affiliate-program/', 'affiliate_network', 'compensation', 'A secondary FlexOffers listing pays 8-12% on sales; the Impact program''s published starting rate of 10% is recorded as the primary route.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://en.wikipedia.org/wiki/Nomad_(eSIM)', 'listing', 'general', 'Wikipedia records Nomad eSIM as a LotusFlare telecommunications service headquartered in Santa Clara, California, launched in 2020, with eSIM data coverage in over 200 destinations and more than 3 million registered users reported by the brand.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 12, 10, 9, 4, '{"niche_fit": "Travel data is a staple recommendation in travel content, and eSIMs are among the most promoted products in the niche.", "ugc_evidence": "The program welcomes content creators with no follower minimum and runs a separate Creator Partner track, though the standard program is publisher-oriented.", "compensation": "A published starting rate of 10% per purchase with higher performance tiers - a solid rate for a low-ticket digital product.", "contact_access": "Application through Impact plus a brand affiliate page with partner contact options; no public affiliate email was verified.", "opportunity_availability": "Publicly open via Impact with no stated follower or website minimum for the standard program.", "credibility": "Established eSIM brand operated by LotusFlare since 2020 with 200+ destination coverage and millions of registered users."}'::jsonb);
