  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cdn.directferries.co.uk/affiliate.htm', 'official_site', 'affiliate', 'Direct Ferries'' own affiliate page (Direct Ferries Connect) states partners earn 50% of the commission Direct Ferries receives from ferry operators on every confirmed sailed booking, with online real-time tracking, and publishes the partnerships email affiliateteam@directferries.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/cruise-affiliate-programs/', 'affiliate_network', 'compensation', 'Network listings conflict with the own-program model: CompareEPC''s data lists a Direct Ferries program on CJ at 2% of sale and FlexOffers lists 1.6% per sale, while the brand''s own program pays a 50% share of the commission it receives - different models, so no single percentage-of-sale rate is recorded.', 'needs_review', now());
