  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 8, 7, 11, 7, 5, '{"niche_fit": "Ferry travel is a real but narrower slice of travel content, strongest for European and island-hopping creators.", "ugc_evidence": "The program is oriented to agents, publishers and booking partners rather than creators specifically; no creator community or content program was found.", "compensation": "A documented earning model exists (50% of the commission the company receives, via its own program; separate network listings at 1.6-2% of sale), but the models conflict so no single rate is recorded.", "contact_access": "A published partnerships email and a dedicated affiliate page on the brand''s own site.", "opportunity_availability": "Partner and affiliate applications are publicly available, subject to approval.", "credibility": "The world''s largest ferry booking platform by its own account, operating 4,000+ routes with 230+ operators."}'::jsonb);
