  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'aloSIM Affiliate Program', 'https://affinityclick.everflowclient.io/affiliate/signup', 'http://alosim.com/blog/alosim-affiliate-esim/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://alosim.com/blog/alosim-affiliate-esim/', 'official_site', 'affiliate', 'aloSIM''s own affiliate page invites influencers, travel agents, bloggers, content creators, publishers, YouTubers and TikTokers to join, and lists among the program benefits ''Fast payouts every month, with no minimum payout requirements'' and ''High earning potential, with no commission caps'' - an explicit no-cap statement on the brand''s own page, so the program is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alosim.com/affiliate-terms-of-service/', 'official_site', 'compensation', 'The brand''s own documents conflict on the rate: its affiliate page describes ''a base commission (starting at 10%)'', while its Affiliate Program Terms of Service (updated August 14, 2025) specify $5.00 USD for each qualifying first-time purchase, and its Everflow listing offers both a 10% plan and a $5 flat plan - so no single commission rate is recorded.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.alosim.com/hc/en-us/articles/23962274615821-Do-you-have-an-aloSIM-affiliate-program', 'official_site', 'contact', 'aloSIM''s support center confirms the affiliate partner program for businesses, media organizations, content creators, influencers and bloggers, gives affiliates@alosim.com as the program contact, and states applicants do not need a blog or a successful social media account.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.crunchbase.com/organization/affinityclick', 'listing', 'general', 'Crunchbase records AffinityClick as a Canadian mobile development company headquartered in Ottawa, Ontario, whose apps include Hushed and aloSIM prepaid mobile data for travelers.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 11, 12, 9, 4, '{"niche_fit": "Travel eSIM data is a staple travel-creator recommendation, and aloSIM explicitly markets to travel audiences.", "ugc_evidence": "The brand''s own pages name influencers, TikTokers and YouTubers as target affiliates and say the brand re-shares affiliate content on its social channels.", "compensation": "Verified uncapped earnings with two documented pay plans (10% base or $5 flat per new sale); the conflict between the brand''s own documents keeps it out of the top band.", "contact_access": "A published program email (affiliates@alosim.com) plus a direct Everflow application link from the brand''s own terms.", "opportunity_availability": "Open application with no minimum payout and no blog or social following required, per the brand''s support center.", "credibility": "Established Canadian provider (AffinityClick, Ottawa) with app-store presence and 200+ country coverage, smaller than the largest eSIM rivals."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Llama Naturals', 'https://www.llamanaturals.com', 'Real-fruit gummy vitamin brand for kids and families, based in Countryside, Illinois. Its whole-food gummies (kids multivitamin, prebiotic & probiotic, elderberry immunity, sleep, and adult lines) are USDA Organic, vegan and made with no added sweeteners or synthetic vitamins; the brand reports 300K+ happy families, 2M+ bottles sold and the number-one whole-food kids vitamin on Amazon in 2025.', 'United States', 'published') returning id into bid;
