  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://llamanaturals.superfiliate.com/portal/sign-up', 'official_site', 'affiliate', 'Llama Naturals runs its affiliate program through its own Superfiliate portal; the sign-up page states affiliates earn 20% commission and give their audience 15% off. A separate VIP portal page states 25%, so the standard public 20% rate is the one recorded. No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
