  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.dirteaworld.com/pages/dirtea-community', 'official_site', 'affiliate', 'DIRTEA''s own community page describes its affiliate program: commission tiers of 10-15% (the 10% base tier is recorded), a 10% audience discount, 30-day attribution, and payment in the first week of each month by bank transfer or store credit, with applications via a linked Typeform. The page publishes the affiliate team contact adam.m@dirteaworld.com. No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
