  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 8, 6, 9, 5, '{"compensation": "Commissions are paid through Shopify Collabs per Shopify''s case study, but the rate is not published anywhere fetched, so this stays low.", "contact_access": "No published partnerships email or public application page was found; entry runs through Shopify Collabs.", "credibility": "Celebrity-backed US brand with a Shopify-published growth case study and national online distribution.", "niche_fit": "High-protein ramen is a highly demonstrable food product built for recipe and taste-test content.", "opportunity_availability": "The Ram Fam actively recruits through Collabs applications and gifting, per Shopify''s case study.", "ugc_evidence": "Strong and quantified: Shopify documents 432 ambassadors, 145+ affiliates and $200K+ in affiliate-driven sales through the Ram Fam program."}'::jsonb);
