  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shopper.com/partnerships/miraclenoodle-com-affiliate-program', 'affiliate_network', 'compensation', 'Third-party rate figures conflict: Shopper lists 5-10% (EPC-derived), commission.academy lists 10-20% and affjumbo lists 6.4%. Because the sources conflict and the brand publishes no rate, commission_rate is recorded as null.', 'needs_review', now());
