  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 7, 12, 8, 4, '{"compensation": "A real ShareASale program exists, but the brand publishes no rate and third-party figures conflict (5-10%, 6.4%, 10-20%), so the rate is null and this stays low.", "contact_access": "A published support email and phone number on the brand''s own homepage, plus a partners page.", "credibility": "Long-running US brand with distribution at Whole Foods, Sprouts, Costco and Walmart.", "niche_fit": "Low-carb noodle swaps are a proven recipe-content staple for keto, gluten-free and GLP-1 creators.", "opportunity_availability": "Both the ShareASale program and the creator-collabs application are publicly described.", "ugc_evidence": "The brand runs a dedicated creator-collabs track and actively solicits tagged recipe UGC on Instagram, though no cohort size is published."}'::jsonb);
