  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.getbeastbites.com', 'listing', 'compensation', 'A third-party creator-offer listing (Payper) shows a 25% commission plus free sample for Beast Bites, but this is not a brand-published TikTok Shop rate, so it is documented here only and not recorded as the commission rate. No earnings-cap statement was found, so the cap is unknown.', 'needs_review', now());
